input_ = {
  "id": "3fa85f64-5717-4562-b3fc-2c963f66afa6",
  "tool_output": "[{\"type\": \"text\", \"text\": \"[{\\\"url\\\":\\\"https://cafef.vn/hang-loat-nguoi-noi-tieng-di-ban-ca-phe-188260924100803705.chn\\\",\\\"content\\\":\\\"Người nổi tiếng bước vào cuộc chơi cà phê\\\\n\\\\nHiện nay, ngày càng nhiều người nổi tiếng Việt tham gia thử sức kinh doanh quán cà phê. Từ những ca sĩ U60 từng đứng trên các sân khấu lớn đến những diễn viên đang được chú ý trên màn ảnh, không ít người lựa chọn F&B như một hướng kinh doanh song song với nghệ thuật.\\\\n\\\\nĐiểm chung của những mô hình này là tận dụng lợi thế rất đặc biệt của nghệ sĩ: độ nhận diện và cộng đồng người hâm mộ lớn. Một quán cà phê mang tên hoặc gắn trực tiếp với hình ảnh nghệ sĩ không đơn thuần là nơi bán đồ uống, mà còn có thể trở thành nơi người hâm mộ gặp thần tượng, chụp ảnh, nghe biểu diễn hoặc tìm kiếm một trải nghiệm khác với quán cà phê thông thường.\\\\n\\\\nTuy nhiên, những diễn biến trong việc kinh doanh cà phê được những người nổi tiếng cập nhật liên tục cũng cho thấy sức hút của người nổi tiếng có thể giúp quán tạo hiệu ứng ban đầu, nhưng chưa chắc đảm bảo mô hình có thể vận hành lâu dài.\\\\n\\\\nHai \\\\\\\"ông hoàng\\\\\\\" U60 cùng đi bán cà phê\\\\n\\\\nCa sĩ Đàm Vĩnh Hưng là một trong những nghệ sĩ gây chú ý nhất khi bước vào lĩnh vực này. Đầu tháng 2/2026, nam ca sĩ khai trương Tiệm Cà Phê Cà Pháo tại khu Thảo Điền, TP.HCM. Những ngày đầu, quán thu hút lượng khách lớn đến mức sau hơn 2 tuần phải tạm đóng cửa vài ngày để điều chỉnh nhân sự, nguyên liệu và quy trình phục vụ. Theo thông tin từ quán, tình trạng quá tải khiến một số khâu vận hành chưa đáp ứng kịp lượng khách.\\\\n\\\\nĐàm Vĩnh Hưng không chỉ đứng tên thương hiệu. Trong thời gian đầu, anh thường xuyên xuất hiện tại quán, trực tiếp đón khách, pha chế, bưng bê, trò chuyện và chụp ảnh cùng người hâm mộ.\\\\n\\\\nSau cơ sở đầu tiên, đến tháng 7, nam ca sĩ mở thêm cơ sở thứ 2 tại đường Nguyễn Thông, TP.HCM. Tháng 9, anh tiếp tục thông báo chuẩn bị đưa Cà Phê Cà Pháo đến Đà Lạt, tại số 2A Bùi Thị Xuân.\\\\n\\\\nCơ sở tại Đà Lạt dự kiến khai trương trong 3 ngày, từ 27-29/9. Đặc biệt, tầng 2 được dành cho khách muốn nghe Đàm Vĩnh Hưng biểu diễn. Như vậy, khai trương đúng kế hoạch, thương hiệu sẽ có 3 cơ sở tại TP.HCM và Đà Lạt.\\\\n\\\\nMột điểm đáng chú ý trong cách làm của Đàm Vĩnh Hưng là biến quán cà phê thành một phần của trải nghiệm nghệ sĩ. Khách không chỉ đến uống cà phê mà còn có cơ hội gặp gỡ, chụp hình hoặc nghe anh hát.\\\\n\\\\nCa sĩ đình đám một thời Đan Trường cũng đang có bước đi tương tự. Tháng 5/2026, anh khai trương Bo\\\\\\'$ Coffee House tại đường Đinh Tiên Hoàng, TP.HCM. Chỉ trong 2 ngày 23-24/5, nam ca sĩ cho biết quán đón hơn 1.300 lượt khách. Riêng ngày thứ hai, quán kín chỗ, thậm chí \\\\\\\"không còn chỗ đứng\\\\\\\".\\\\n\\\\nĐến tháng 9, Đan Trường thông báo đưa thương hiệu ra Bắc. Cơ sở tại Quảng trường 3/2, TP Bắc Ninh dự kiến khai trương ngày 16/10.\\\\n\\\\nKhông dừng ở thị trường trong nước, tại Mỹ, nam ca sĩ cũng phát triển thương hiệu Cafés Quán và chuẩn bị mở thêm cơ sở tại San Jose vào tháng 10.\\\\n\\\\nVới Đan Trường, kinh doanh cà phê không phải một dự án đơn lẻ mà đang được triển khai có hệ thống ở cả Việt Nam và Mỹ, song song với hoạt động nghệ thuật.\\\\n\\\\nNhưng không phải người nổi tiếng nào cũng giữ được quán\\\\n\\\\nNếu Đàm Vĩnh Hưng và Đan Trường đang mở rộng, câu chuyện của nghệ sĩ Cát Tường lại đi theo hướng khác.\\\\n\\\\nTháng 6/2025, nữ nghệ sĩ mở Tiệm Cà Phê Cát Tường 1977 tại TP.HCM. Cô cho biết đã đầu tư khoảng 400 triệu đồng để sửa chữa căn nhà và thiết kế không gian theo phong cách hoài cổ. Giá bán được định hướng bình dân, khoảng 25.000 đồng/ly. Thế nhưng sau hơn 9 tháng, Cát Tường quyết định đóng cửa.\\\\n\\\\nTheo chia sẻ của nữ nghệ sĩ, những ngày đông khách nhất, doanh thu quán đạt khoảng 3 triệu đồng/ngày. Trong khi đó, quán phải duy trì nhân sự, thuê bãi giữ xe và gánh các chi phí vận hành khác.\\\\n\\\\nCó thời điểm, quán phải bù lỗ. Cát Tường thậm chí lấy tiền túi để trả lương cho nhân viên.\\\\n\\\\nMột nguyên nhân đáng chú ý là sự phụ thuộc vào chính người nổi tiếng. Cát Tường nhận ra một bộ phận khách đến quán chủ yếu vì muốn gặp cô. Có khách còn gọi điện hỏi trước xem cô có ở quán hay không rồi mới quyết định đến.\\\\n\\\\nĐiều này tạo ra một nghịch lý: người chủ vừa là lợi thế để kéo khách, vừa có thể trở thành một phần của bài toán vận hành. Khi Cát Tường phải đi quay phim, diễn sân khấu hoặc công tác, cô không thể thường xuyên có mặt tại quán. Nhưng nếu thiếu sự xuất hiện của \\\\\\\"bà chủ nổi tiếng\\\\\\\", sức hút với một bộ phận khách cũng giảm xuống. Sau một thời gian, nữ nghệ sĩ nhận thấy việc kinh doanh ảnh hưởng đáng kể đến công việc và thời gian cá nhân nên quyết định dừng lại.\\\\n\\\\nKhông chỉ các nghệ sĩ kỳ cựu, năm 2026 cũng xuất hiện những gương mặt trẻ hơn thử sức với F&B. Đầu tháng 6, diễn viên Steven Nguyễn khai trương một quán cà phê tại phường Hòa Hưng, TP.HCM. Trong ngày đầu, lượng khách đến vượt dự kiến, nhiều người phải xếp hàng mua nước, trong khi khu vực bên trong quán kín chỗ.\\\\n\\\\nSteven Nguyễn cũng trực tiếp có mặt tại quán để pha chế, phục vụ và chụp ảnh cùng khách. Sức hút đến từ cả lượng người hâm mộ của nam diễn viên lẫn sự chú ý dành cho anh sau những dự án điện ảnh gần đây.\\\\n\\\\nNgoài ra còn nhiều nghệ sĩ khác cũng thử sức kinh doanh quán cà phê như diễn viên Hải Triều mở quán tại Quận 1 và nhanh chóng rơi vào cảnh quá tải vì lượng khách lớn, phải lên tiếng xin lỗi. Trong khi đó, Tiến Luật khai trương C13 Coffee tại khu Sala, trực tiếp tham gia vận hành và xem đây là một thử sức kinh doanh bên cạnh hoạt động nghệ thuật....\\\\n\\\\nMột ly cà phê cần nhiều hơn sức hút của người nổi tiếng\\\\n\\\\nTrường hợp này cho thấy mô hình đang được nhiều nghệ sĩ lựa chọn: Chính nghệ sĩ trở thành một phần của thương hiệu. Ngày khai trương có thể là một sự kiện truyền thông. Người hâm mộ trở thành những vị khách đầu tiên. Những hình ảnh xếp hàng, kín chỗ lại tiếp tục tạo hiệu ứng trên mạng xã hội.\\\\n\\\\nDanh tiếng có thể giúp một quán cà phê có lượng khách ban đầu, nhưng không tự động biến thành hiệu quả kinh doanh dài hạn. Nhưng sau ngày khai trương, bài toán trở lại rất thực tế.\\\\n\\\\nĐàm Vĩnh Hưng từng phải tạm đóng cửa cơ sở đầu tiên để điều chỉnh vì lượng khách quá đông, nhưng sau đó tiếp tục mở thêm địa điểm. Đan Trường cũng nhanh chóng đưa mô hình từ TP.HCM ra Bắc Ninh và duy trì hoạt động kinh doanh tại Mỹ.\\\\n\\\\nTrong khi đó, Cát Tường phải dừng lại sau hơn 9 tháng vì doanh thu không đủ bù chi phí và mô hình phụ thuộc khá nhiều vào sự xuất hiện của chính cô.\\\\n\\\\nVới nghệ sĩ, lợi thế lớn nhất có thể là lượng người hâm mộ sẵn có. Nhưng để biến những người đến vì tò mò, yêu mến thần tượng thành khách hàng quay lại thường xuyên, quán vẫn phải giải quyết những bài toán rất truyền thống của F&B: sản phẩm, giá bán, vị trí, trải nghiệm, nhân sự và chi phí vận hành.\\\\n\\\\nSau cùng, khi ánh đèn sân khấu tắt và nghệ sĩ không có mặt tại quầy, thứ giữ chân khách có lẽ vẫn là chất lượng của chính ly cà phê và trải nghiệm mà quán mang lại.\\\\n\\\\nẢnh: Tổng hợp\\\"},{\\\"url\\\":\\\"https://kenh14.vn/khong-mo-duoc-nhac-ban-quyen-nen-quan-ca-phe-o-tphcm-moi-han-dan-tranh-sao-truc-den-bieu-dien-ly-nuoc-95000-dong-kin-cho-hang-dem-215260823141415161.chn\\\",\\\"content\\\":\\\"Nếu đã quen với những quán cà phê có acoustic, band nhạc hay DJ, trải nghiệm ở một quán tại khu Chợ Lớn, TP.HCM lại khá khác. Càng nghe, khung cảnh càng có cảm giác như một “concert” phiên bản rất đời thường.\\\\n\\\\nĐó là điều Có như lời đồn bắt gặp tại Vệt Nâu Cafe, một quán cà phê ở khu vực Quận 6 cũ, nơi những buổi tối bình thường bỗng có thêm màu sắc đặc biệt với tiếng đàn tranh và sáo trúc vang lên ngay giữa không gian mở.\\\\n\\\\nTrải nghiệm \\\\\\\"concert vỉa hè\\\\\\\", uống cà phê nghe đàn tranh, sáo trúc có gì?\\\\n\\\\nKhi quán cà phê cũng là sân khấu\\\\n\\\\nVệt Nâu Cafe nằm tại 247 Chợ Lớn, Phường Bình Phú, TP.HCM, khu vực trước đây thuộc Quận 6, cách trung tâm thành phố khá xa nhưng vẫn đều đặn đón một lượng khách không nhỏ vào mỗi tối cuối tuần và giữa tuần. Quán mở cửa hằng ngày từ 7 giờ sáng đến 10 giờ tối, phục vụ như một quán cà phê bình thường vào ban ngày. Chỉ riêng khung giờ từ 19h30 đến 21h30 các tối thứ Tư, Năm, Sáu, Bảy và Chủ nhật mới có nhạc sống, còn lại quán vẫn mở bán bình thường, không biểu diễn.\\\\n\\\\nQuán được xây theo kiểu một trệt một lầu, sở hữu hai mặt tiền trên đường Chợ Lớn. Tầng trệt là không gian mở, thoáng ra phía đường phố, còn tầng một là khu vực có máy lạnh dành cho khách muốn ngồi mát. Vào những đêm có biểu diễn, cả tầng trệt lẫn tầng lầu đều kín chỗ tạo nên khung cảnh vô cùng đông đúc.\\\\n\\\\nNgười tạo nên không khí đặc biệt vào tối thứ Năm là hai bạn trẻ Thanh Hùng chơi đàn tranh và Tú Trần chơi sáo trúc. Cả hai xuất hiện trong trang phục áo dài, cổ phục Việt, mang đến một hình ảnh vừa cổ điển vừa gần gũi. Điều thú vị nằm ở cách họ chọn bài để trình diễn, không đóng khung trong nhạc truyền thống mà phối lại nhiều ca khúc quen thuộc với đời sống hằng ngày. Đó có thể là những bài nhạc đám cưới đám tiệc miền Tây, cũng có thể là những bản Pop, Ballad quen tai. Trong đó, tiết mục khiến nhiều khách nán lại lâu nhất và cũng là lý do kéo không ít người tìm đến quán chính là bản phối ca khúc Hồng Nhan, được thể hiện qua tiếng đàn tranh và sáo trúc theo một màu sắc khác hẳn bản gốc.\\\\n\\\\nSức hút của những buổi diễn này không chỉ dừng lại ở phạm vi quán. Các đoạn clip ghi lại phần trình diễn của Thanh Hùng và Tú Trần lan truyền mạnh trên mạng xã hội, giúp Vệt Nâu Cafe trở thành cái tên được nhắc đến nhiều dù nằm khá xa khu trung tâm thành phố. Cũng chính vì độ viral này mà nhiều cư dân mạng gọi vui buổi diễn là concert 0 đồng, khi chỉ cần gọi một ly nước là có thể ngồi thưởng thức trọn hai giờ đồng hồ âm nhạc.\\\\n\\\\nBạn Minh Thư, một người từng ghé quán trải nghiệm, chia sẻ rằng nghe những bản nhạc quen thuộc được phối lại bằng đàn tranh và sáo trúc mang lại cảm giác như đang lạc vào một khung cảnh phim cổ trang giữa lòng phố thị.\\\\n\\\\nTuy nhiên, cái tên concert 0 đồng giờ đây có lẽ không còn chính xác. Vì muốn có một chỗ ngồi ưng ý để vừa nhâm nhi ly nước vừa thưởng thức trọn vẹn buổi diễn, nhiều người đã chọn cách đến thật sớm nhờ hiệu ứng lan truyền trên mạng xã hội. Có Như Lời Đồn có mặt tại quán đúng 19h30, thời điểm buổi diễn bắt đầu, nhưng menu nước lúc này đã vơi đi đáng kể, chỉ còn lại vài lựa chọn ít ỏi.\\\\n\\\\nMenu gọn, giá đổi theo khung giờ\\\\n\\\\nDù mang tên cà phê, thức uống tại Vệt Nâu Cafe lại không quá đa dạng. Menu xoay quanh cà phê, trà trái cây, thức uống nóng, nước ép, trà sữa và sữa chua, mỗi loại chỉ có khoảng hai đến ba lựa chọn. Một điểm khá đặc biệt là mức giá tại đây thay đổi tùy theo việc khách có ngồi ở khu vực xem biểu diễn hay không, và chỉ áp dụng vào những khung giờ có nhạc sống. Nếu chọn chỗ ngồi bên ngoài khu vực biểu diễn, các loại nước sẽ đồng giá 65.000 đồng. Còn nếu muốn có vị trí thuận tiện để xem trọn buổi diễn, mức giá sẽ là 95.000 đồng cho ly size lớn. Vào ban ngày hoặc những thời điểm quán chưa vào giờ diễn, menu vẫn bán theo giá thông thường của một quán cà phê, dao động khoảng 25.000 đến 55.000 đồng mỗi món, rẻ hơn đáng kể so với giá giờ vàng buổi tối.\\\\n\\\\nCó thể thấy cách định giá này gắn liền với trải nghiệm âm nhạc nhiều hơn là đồ uống, và điều đó cũng phần nào phản ánh qua chất lượng thức uống mà Có Như Lời Đồn được phục vụ vào buổi tối. Hai món được gọi thử là một ly cà phê đen và một ly trà sữa phong lan, cả hai đều không để lại ấn tượng gì đặc biệt, hương vị khá nhạt so với mức giá phải trả. Dù được gọi là size lớn nhưng thể tích thực tế của cả hai ly lại không khác gì so với một ly size nhỏ thông thường ở các quán khác, khiến phần đồ uống chưa thực sự tương xứng với số tiền bỏ ra.\\\\n\\\\nĐiều khiến người ta muốn quay lại không nằm ở ly nước\\\\n\\\\nNhìn tổng thể, Vệt Nâu Cafe đang chọn cách xây dựng trải nghiệm dựa trên âm nhạc nhiều hơn là hương vị thức uống, và đó cũng là điều làm nên sự khác biệt của quán so với vô số quán cà phê khác trong thành phố. Suốt khoảng hai giờ đồng hồ, tiếng đàn tranh và sáo trúc vang lên giữa không gian vỉa hè đông đúc mang đến một cảm giác vừa lạ vừa quen, đặc biệt với những ai từng lớn lên cùng những giai điệu dân tộc nhưng ít có dịp nghe trực tiếp giữa đời sống thường ngày.\\n\\nĐây cũng là một hướng đi đáng chú ý trong bối cảnh nhiều quán cà phê gần đây phải tìm cách làm mới trải nghiệm âm nhạc cho khách trước những thay đổi liên quan đến bản quyền âm nhạc tại các cơ sở kinh doanh. Thay vì mở playlist quen thuộc, việc mời các bạn trẻ biểu diễn trực tiếp bằng nhạc cụ dân tộc vừa giúp quán tạo dấu ấn riêng, vừa mở ra một sân khấu nhỏ cho những người theo đuổi nhạc cụ truyền thống.\\n\\nNếu chỉ xét riêng về đồ uống, Vệt Nâu Cafe khó có thể ghi điểm với những ai khó tính về hương vị, vì menu ít lựa chọn và giá buổi tối không hề rẻ. Nhưng nếu đến đây với tâm thế thưởng thức một buổi hòa tấu nhạc cụ dân tộc giữa lòng thành phố, chỉ với chi phí của một ly nước, thì đây vẫn là một trải nghiệm đáng thử, và cũng dễ hiểu vì sao nó đã trở thành hiện tượng được truyền tay nhau khắp các nền tảng mạng xã hội trong thời gian gần đây. Ai muốn ghé vào tối thứ Năm để nghe đàn tranh sáo trúc, tiết mục nổi tiếng nhất tại quán, nên đến thật sớm trước 19 giờ để có chỗ ngồi đẹp và không bỏ lỡ những món nước ít ỏi trên menu. Còn nếu chỉ muốn ghé uống nước bình thường vào ban ngày với mức giá dễ chịu hơn, khách có thể đến bất cứ lúc nào trong khung giờ mở cửa.\\\\n\\\\nVệt Nâu Cafe\\\\n\\\\nĐịa chỉ: 247 Chợ Lớn, Quận 6, TP.HCM (nay thuộc Phường Bình Phú)\\\\n\\\\nGiờ mở cửa: 07h00 đến 22h00 hằng ngày\\\\n\\\\nKhung giờ nhạc: 19h30 đến 21h30\\\\n\\\\nĐàn tranh, sáo trúc: tối thứ Năm hằng tuần\\\\n\\\\nAcoustic: tối thứ Bảy và Chủ nhật\\\\n\\\\nSaxophone: tối thứ Tư và thứ Sáu hằng tuần\\\\n\\\\nGiá nước giờ diễn: 65.000 đồng (khu không xem diễn) hoặc 95.000 đồng ly lớn (khu xem diễn)\\\\n\\\\nGiá nước ngoài giờ diễn: khoảng 25.000 đến 55.000 đồng\\\"},{\\\"url\\\":\\\"https://dantri.com.vn/kinh-doanh/chuoi-highlands-katinat-phuc-long-ban-ca-phe-khong-gian-va-o-dien-20260924221151963.htm\\\",\\\"content\\\":\\\"Anh Trường, nhân viên văn phòng tại TPHCM, thường chi khoảng 50.000-60.000 đồng mỗi ngày để “cắm máy” tại các quán cà phê. Mỗi lần đến quán, anh có thể ngồi 5-7 tiếng làm việc liên tục.\\\\n\\\\nTheo anh, cà phê không còn đơn thuần là nơi thưởng thức đồ uống. Với những người thường xuyên làm việc bên ngoài văn phòng, quán cà phê có thể trở thành một nơi làm việc, giúp thay đổi không gian và tạo sự thoải mái hơn so với việc ngồi cả ngày tại công ty.\\\\n\\\\nVì vậy, cùng với cà phê, các loại đồ uống, điều anh quan tâm hơn là không gian có rộng rãi, thoáng mát hay không, bàn ghế có thuận tiện để làm việc hay không và đặc biệt là có đủ ổ điện để sạc laptop, điện thoại...\\\\n\\\\n“Những nơi có vị trí rộng, nhiều ổ điện tiện cho sạc pin máy tính hay các đồ công nghệ phục vụ cho công việc, tôi sẽ ưu tiên. Còn nơi nào hạn chế ổ sạc, tôi sẽ chỉ đến nếu như không còn lựa chọn”, anh Trường nói.\\\\n\\\\nBán cà phê, bán dịch vụ, bán không gian, bán cả ổ điện!\\\\n\\\\nChia sẻ với phóng viên Dân trí, một nhóm bạn trẻ làm việc trong một công ty giải trí ở phường Xuân Hòa (TPHCM) cho biết mỗi ngày, cả nhóm thường rủ nhau qua quán cà phê đối diện công ty để đổi không khí - một cách tái tạo năng lượng, thư giãn đầu óc để tạo hiệu quả. Chi phí mỗi lần ra quán không dưới 50.000 đồng/người.\\\\n\\\\nTính ra mỗi tháng chi phí cho quán cà phê hơn 1 triệu đồng, chưa kể gọi thêm đồ ăn các loại hoặc có ngày ra quán 2-3 lần nếu công việc gấp phải chạy KPI liên tục.\\\\n\\\\nXu hướng làm việc tự do tại không gian quán cà phê ngày càng trở nên phổ biến. Không ít người dành 8-10 tiếng mỗi ngày để \\\\\"cắm rễ\\\\\\\" ở quán cà phê làm việc và học tập.\\\\n\\\\nTrong bối cảnh này, các chuỗi cà phê đang bước vào \\\\\"cuộc chiến\\\\\\\" khốc liệt khi tệp khách hàng ngày càng mở rộng, nhu cầu theo đó cũng đa dạng hơn. Các quán bán cà phê, bán không gian, lối sống và cả ổ điện!\\\\n\\\\nMột sự vụ liên quan vào giữa năm 2025, khi thông tin về việc một số chi nhánh của chuỗi cà phê The Coffee House bịt kín các ổ điện đã gây nhiều tranh cãi.\\\\n\\\\nKhông chỉ ứng xử đi ngược nhu cầu của đại đa số khách, mà còn bởi trước đó “điểm khác biệt” theo giới thiệu của chuỗi cà phê này là thiết kế không gian để người trẻ có thể đến để học tập, làm việc.\\\\n\\\\nSau đó, The Coffee House đã có giải thích rằng chỉ đang thực hiện một số điều chỉnh nhỏ trong thiết kế không gian… Dù vậy, thương hiệu có lẽ cũng đã ghi điểm trừ trong lòng khách hàng.\\\\n\\\\nHiện tại, ghi nhận của phóng viên Dân trí ở một quán cà phê của chuỗi The Coffee House trên đường Mạc Đĩnh Chi (TPHCM), nhân viên cho biết nếu khách thông thường có thể dùng cà phê, trà và bánh ở lầu 1 (không có ổ điện, chỉ có cổng kết nối USD - type C). Nếu muốn lên không gian nghiên cứu, học tập khách sẽ sử dụng ở lầu 2 của quán, có ổ điện.\\\\n\\\\nỞ góc độ khác, Trang Thư (sinh năm 2000), nhân viên văn phòng và đang theo học chương trình thạc sĩ, lại tránh các chuỗi lớn khi cần tìm nơi làm việc hoặc học nhóm.\\\\n\\\\n“Tôi không chọn các quán chuỗi nằm ở các góc ngã 3, ngã 4 hoặc khu vực sầm uất vì nhìn vào là thấy đông. Khách ra vào liên tục thì nhân viên phải đi tìm bàn trống cho khách mới, nên ngồi quá 3-4 tiếng cũng thấy ngại”, Trang Thư nói.\\\\n\\\\nThay vào đó, cô tìm đến những quán cà phê địa phương có phong cách cổ điển, yên tĩnh và ít người. Đổi lại, mức giá phải trả cao hơn đáng kể, nhưng phần chênh lệch này không hẳn chỉ nằm ở chất lượng cà phê mà còn là chi phí cho việc “được ngồi lâu” và một không gian được đầu tư để khách có thể làm việc, học tập hoặc chụp ảnh.\\\\n\\\\nNhững vị khách như Trang Thư đang giúp một ngách phân khúc cà phê khác nổi lên tại Việt Nam và được ưa chuộng: Sản phẩm đặc sản dành cho người có gu.\\\\n\\\\nỔ điện được thay bằng cổng sạc USD ở một quán cà phê (Ảnh: Lê Tỉnh).\\n\\\\nCà phê đặc sản, có gu lên ngôi\\\\n\\\\nTheo ghi nhận, thị trường cà phê đặc sản toàn cầu có thể đạt quy mô 183 tỷ USD vào năm 2030, với tốc độ tăng trưởng trung bình khoảng 10% mỗi năm. Tại Việt Nam, nhu cầu này cũng ngày càng gia tăng, thể hiện qua sự phát triển của các thương hiệu chọn lối đi riêng trên thị trường.\\\\n\\\\nKhởi đầu từ năm 2021 từ một đơn vị rang xay, Every Half đang phát triển thành chuỗi bán lẻ cà phê đặc sản. Hiện thương hiệu sở hữu 35 cửa hàng trên toàn quốc, tăng 157% về quy mô mạng lưới so với năm trước. Chuỗi cà phê này được thành lập bởi Võ Duy Phú và Trần Lê Minh Trúc, sự kết hợp giữa hai người từng có thời gian làm việc tại The Coffee House.\\\\n\\\\nDù không công bố chỉ số kinh doanh, song hiệu quả hoạt động tốt giúp thương hiệu huy động được tốt dòng vốn đầu tư. Công ty này vừa công bố hoàn tất vòng gọi vốn trị giá 8 triệu USD, với toàn bộ khoản đầu tư đến từ hai quỹ hiện hữu là Openspace Capital và DSG Consumer Partners.\\\\n\\\\nMột set đồ uống tại chuỗi cà phê đặc sản mới ở TPHCM, có thông điệp kèm theo gửi tới khách hàng (Ảnh: Tri Túc).\\n\\\\nRang Rang Coffee hay The Running Beans cũng đang khai thác tốt phân khúc này, dù quy mô còn nhỏ chỉ dừng ở 10 cửa hàng đổ lại. Song, với hương vị cà phê riêng biệt và đa dạng, đây là những thương hiệu được nhiều khách hàng lựa chọn do khẩu vị, thể hiện lối sống riêng.\\\\n\\\\n\\\"Cuộc chiến\\\\\\\" giữa các thương hiệu: Các bên phải chú trọng điều gì để giữ khách?\\\\n\\\\nSự thay đổi trong cách khách sử dụng quán cà phê cũng đặt các chuỗi trước một bài toán khác: điều gì sẽ là lý do chính để khách lựa chọn thương hiệu?\\\\n\\\\nTừ góc độ người kinh doanh, bà Đỗ Thanh Yến Nhi, Giám đốc công ty Cổ phần Trà cà phê An Nhiên (Anni Coffee), cho rằng hành vi khách hàng đang phân hóa khá rõ theo từng nhóm. Nhóm khách trẻ có xu hướng nhanh chóng bắt nhịp các trào lưu và có thể đổ xô đến những quán đang “hot” trên mạng xã hội, dù sức hút có thể chỉ kéo dài trong một thời gian.\\\\n\\\\nTrong khi đó, nhóm khách văn phòng và lớn tuổi hơn quan tâm nhiều hơn đến phong cách và bản sắc thương hiệu. Những khác biệt này cho thấy cuộc cạnh tranh của thị trường cà phê không diễn ra theo một công thức duy nhất. Có chuỗi chọn không gian lớn, vị trí thuận tiện và khả năng phục vụ lượng khách đông. Có thương hiệu tập trung vào trải nghiệm riêng biệt, sự yên tĩnh hoặc bản sắc. Cũng có mô hình không đặt nặng việc xây dựng một không gian để khách ngồi lâu.\\\\n\\\\nThay vì chạy theo cuộc đua mở những cửa hàng lớn, Anni Coffee theo đuổi mô hình xe cà phê nhượng quyền trong khoảng 5 năm qua.\\\\n\\\\n\\\"Chi phí đầu tư cho một xe cà phê nhượng quyền của Anni Coffee khoảng 49 triệu đồng, gồm xe và combo thiết bị. Nhóm khách nhận nhượng quyền chủ yếu là phụ nữ khởi nghiệp và những người kinh doanh nhỏ lẻ tại nhiều tỉnh thành. Để duy trì chất lượng đồng nhất, hợp đồng nhượng quyền yêu cầu bên nhận nhượng quyền lấy nguyên liệu cà phê trực tiếp từ công ty\\\", bà Nhi nói.\\\\n\\\\nÔng Hoàng Tùng - chuyên gia F&B - cho rằng sự khác biệt giữa các chuỗi không nằm ở một yếu tố riêng lẻ như vị trí hay sản phẩm, mà nằm ở khả năng vận hành cả một hệ thống kinh doanh. Theo vị chuyên gia này, một hệ thống \\\\\"khỏe\\\\\\\" cần hội tụ 4 yếu tố.\\\\n\\\\nThứ nhất, năng lực quản trị phải bao quát từ con người, đào tạo, chuỗi cung ứng đến kiểm soát chất lượng.\\\\n\\\\nÔng Hoàng Tùng - chuyên gia F&B (Ảnh: Nhân vật cung cấp).\\n\\\\nThứ hai, phải chọn địa điểm có đủ khách mục tiêu và doanh thu đủ sức gánh chi phí mặt bằng. Thời của việc mở điểm ồ ạt đã qua, nhiều chuỗi hiện phải quay lại với bài toán lợi nhuận trên từng cửa hàng cụ thể.\\\\n\\\\nThứ ba, thấu hiểu khách hàng, nếu không còn hiểu khách hàng nữa nên bị quay lưng.\\\\n\\\\nThứ tư, cần tối ưu chi phí, bởi doanh thu lớn chưa chắc có lợi nhuận nếu chi phí thuê mặt bằng, nhân sự, nguyên liệu và quản lý tăng quá nhanh.\\\\n\\\\nChuyên gia dẫn chứng, sau giai đoạn tăng trưởng nóng, nhiều chuỗi đã phải quay về bài toán căn cơ hơn, bắt đầu lại từ việc tối ưu chi phí.\\\\n\\\\n(Còn tiếp)...\\\"]\\u00\", \"tool_name\": \"search_internet\", \"input_message\": \"Bình Thạnh có quán cà phê nào nổi tiếng\"}  ",
  "tool_name": "search_internet",
  "input_message": "Bình Thạnh có quán cà phê nào nổi tiếng"
}


llm = create_gemini_llm(
    model_name="gemini-3.1-flash-lite",
    api_key=api_key,
    temperature=0,
)

prompt_template = [
    {
        "role": "system",
        "content": (
            "Role: Bạn là một người bạn tư vấn thông minh, am hiểu về tài chính và kinh doanh. "
            "Khi trả lời, hãy nói chuyện tự nhiên như đang trò chuyện trực tiếp với người khác, "
            "không đọc lại thông tin, không lặp lại ngữ cảnh. "
            "Không dùng các cụm từ như: 'Nội dung bạn cung cấp nói về', 'Dựa trên thông tin bạn đưa ra', "
            "'Theo context', 'Tham khảo từ', 'Thông tin bạn cung cấp', hay bất kỳ cụm từ nào tỏ ra bạn đang đọc lại dữ liệu. "
            "Trả lời như thể bạn đã biết thông tin đó và đang chia sẻ lại một cách tự nhiên. "
            "Chỉ sử dụng thông tin có trong context, không tự nghĩ ra thêm gì ngoài context. "
            "Nếu có URL trong context, đưa vào cuối câu trả lời dưới dạng link tham khảo bình thường.\n"
            "\n"
            "---\n"
            "\n"
            "### Luồng xử lý:\n"
            "1. Xác định câu hỏi của người dùng có liên quan đến tài chính, kinh doanh, tin tức, thị trường chứng khoán hay không.\n"
            "2. Trả lời tương ứng:\n"
            "- Nếu KHÔNG liên quan: tóm tắt nội dung context ngắn gọn (khoảng 100 từ) bằng giọng tự nhiên, rồi đề cập nhẹ nhàng rằng câu hỏi không thuộc lĩnh vực tài chính và hỏi người dùng có muốn chuyển sang câu hỏi khác về tài chính không.\n"
            "- Nếu CÓ liên quan: trả lời chi tiết, đầy đủ dựa trên context bằng ngôn ngữ tài chính.\n"
            "3. Nếu có URL trong context, đính kèm ở cuối câu trả lời.\n"
        ),
    },
    {
        "role": "user",
        "content": (
            "Câu hỏi: {user_query}\n"
            "Context: {context}\n\n"
            "Hãy trả lời câu hỏi trên."
        ),
    },
]

prompt_template = ChatPromptTemplate.from_messages(prompt_template)

chain = prompt_template | llm
user_query = input_["input_message"]
context = input_["tool_output"]

response = chain.invoke(
    {
        "user_query": user_query,
        "context": context
    }
)
print(response.content[0].get("text"))
